content:
650              detach_client(self);
   651          h2o_send(req, NULL, 0, H2O_SEND_STATE_FINAL);
   652          return NULL; /* TODO this returning NULL causes keepalive to be disabled in http1client. is this what we intended? */
   653      }
   654
   655      /* switch to using pipe reader, if the opportunity is provided */
   656      if (args->pipe_reader != NULL) {
   657  #ifdef __linux__
   658          if (pipe2(self->pipe_reader.fds, O_NONBLOCK | O_CLOEXEC) != 0) {
   659              char errbuf[256];
   660              h2o_fatal("pipe2(2) failed:%s", h2o_strerror_r(errno, errbuf, sizeof(errbuf)));
   661          }
   662          args->pipe_reader->fd = self->pipe_reader.fds[1];
   663          args->pipe_reader->on_body_piped = on_body_piped;
   664  #endif
   665      }
   666
   667      /* if httpclient has no received body at this time, immediately send only headers using zero timeout */
   668      h2o_timer_link(req->conn->ctx->loop, 0, &self->send_headers_timeout);
   669
   670      return on_body;
   671  }
