   673  static int on_1xx(h2o_httpclient_t *client, int version, int status, h2o_iovec_t msg, h2o_header_t *headers, size_t num_headers)
   674  {
   675      struct rp_generator_t *self = client->data;
   676      size_t i;
   677
   678      for (i = 0; i != num_headers; ++i) {
   679          if (headers[i].name == &H2O_TOKEN_LINK->buf)
   680              h2o_push_path_in_link_header(self->src_req, headers[i].value.base, headers[i].value.len);
   681      }
   682
   683      if (status != 101) {
   684          self->src_req->res.status = status;
   685          self->src_req->res.headers = (h2o_headers_t){headers, num_headers, num_headers};
   686          h2o_send_informational(self->src_req);
   687      }
   688
   689      return 0;
   690  }
