   692  static void proceed_request(h2o_httpclient_t *client, const char *errstr)
   693  {
   694      struct rp_generator_t *self = client->data;
   695      if (self == NULL)
   696          return;
   697      if (errstr != NULL)
   698          detach_client(self);
   699      if (self->src_req->proceed_req != NULL)
   700          self->src_req->proceed_req(self->src_req, errstr);
   701  }
