   703  static int write_req(void *ctx, int is_end_stream)
   704  {
   705      struct rp_generator_t *self = ctx;
   706      h2o_httpclient_t *client = self->client;
   707      h2o_iovec_t chunk = self->src_req->entity;
   708
   709      assert(chunk.len != 0 || is_end_stream);
   710
   711      if (client == NULL) {
   712          return -1;
   713      }
   714
   715      if (is_end_stream) {
   716          self->src_req->write_req.cb = NULL;
   717          self->req_done = 1;
   718          if (self->res_done)
   719              detach_client(self);
   720      }
   721
   722      return client->write_req(client, chunk, is_end_stream);
   723  }
