   725  static h2o_httpclient_head_cb on_connect(h2o_httpclient_t *client, const char *errstr, h2o_iovec_t *method, h2o_url_t *url,
   726                                           const h2o_header_t **headers, size_t *num_headers, h2o_iovec_t *body,
   727                                           h2o_httpclient_proceed_req_cb *proceed_req_cb, h2o_httpclient_properties_t *props,
   728                                           h2o_url_t *origin)
   729  {
   730      struct rp_generator_t *self = client->data;
   731      h2o_req_t *req = self->src_req;
   732      int use_proxy_protocol = 0, reprocess_if_too_early = 0;
   733
   734      copy_stats(self);
   735
   736      if (errstr != NULL) {
   737          detach_client(self);
   738          h2o_req_log_error(self->src_req, "lib/core/proxy.c", "%s", errstr);
   739          h2o_send_error_502(self->src_req, "Gateway Error", errstr, 0);
   740          return NULL;
   741      }
   742
   743      assert(origin != NULL);
   744
   745      if (req->overrides != NULL) {
   746          use_proxy_protocol = req->overrides->use_proxy_protocol;
   747          req->overrides->location_rewrite.match = origin;
   748          if (!req->overrides->proxy_preserve_host) {
   749              req->scheme = origin->scheme;
   750              req->authority = origin->authority;
   751          }
   752          h2o_iovec_t append = req->path;
   753          if (origin->path.base[origin->path.len - 1] == '/' && append.base[0] == '/') {
   754              append.base += 1;
   755              append.len -= 1;
   756          }
   757          req->path = h2o_concat(&req->pool, origin->path, append);
   758          req->path_normalized =
   759              h2o_url_normalize_path(&req->pool, req->path.base, req->path.len, &req->query_at, &req->norm_indexes);
   760      }
   761
   762      reprocess_if_too_early = h2o_conn_is_early_data(req->conn);
   763      h2o_headers_t headers_vec = (h2o_headers_t){NULL};
   764      build_request(req, method, url, &headers_vec, props,
   765                    !use_proxy_protocol && h2o_socketpool_can_keepalive(client->connpool->socketpool), self->client->upgrade_to,
   766                    use_proxy_protocol, &reprocess_if_too_early, origin);
   767      *headers = headers_vec.entries;
   768      *num_headers = headers_vec.size;
   769
   770      if (reprocess_if_too_early)
   771          req->reprocess_if_too_early = 1;
   772
   773      *body = h2o_iovec_init(NULL, 0);
   774      *proceed_req_cb = NULL;
   775      self->req_done = 1;
   776      if (self->src_req->entity.base != NULL) {
   777          *body = self->src_req->entity;
   778          if (self->src_req->proceed_req != NULL) {
   779              *proceed_req_cb = proceed_request;
   780              self->src_req->write_req.cb = write_req;
   781              self->src_req->write_req.ctx = self;
   782              self->req_done = 0;
   783          }
   784      }
   785      self->client->informational_cb = on_1xx;
   786
   787      client->get_conn_properties(client, &req->proxy_stats.conn);
   788
   789      { /* indicate to httpclient if use of pipe is preferred */
   790          h2o_conn_t *conn = self->src_req->conn;
   791          switch (conn->ctx->globalconf->proxy.zerocopy) {
   792          case H2O_PROXY_ZEROCOPY_ALWAYS:
   793              props->prefer_pipe_reader = 1;
   794              break;
   795          case H2O_PROXY_ZEROCOPY_ENABLED:
   796              if (conn->callbacks->can_zerocopy != NULL && conn->callbacks->can_zerocopy(conn))
   797                  props->prefer_pipe_reader = 1;
   798              break;
   799          default:
   800              break;
   801          }
   802      }
   803
   804      return on_head;
   805  }
