   807  static void on_generator_dispose(void *_self)
   808  {
   809      struct rp_generator_t *self = _self;
   810      do_close(self);
   811
   812      if (self->last_content_before_send != NULL) {
   813          h2o_buffer_dispose(&self->last_content_before_send);
   814      }
   815      h2o_doublebuffer_dispose(&self->sending);
   816      if (self->generator_disposed != NULL)
   817          *self->generator_disposed = 1;
   818  }
