   820  static struct rp_generator_t *proxy_send_prepare(h2o_req_t *req)
   821  {
   822      struct rp_generator_t *self = h2o_mem_alloc_shared(&req->pool, sizeof(*self), on_generator_dispose);
   823
   824      self->super.proceed = do_proceed;
   825      self->super.stop = do_stop;
   826      self->src_req = req;
   827      self->generator_disposed = NULL;
   828      self->client = NULL; /* when connection establish timeouts, self->client remains unset by `h2o_httpclient_connect` */
   829      self->had_body_error = 0;
   830      self->up_req.is_head = h2o_memis(req->method.base, req->method.len, H2O_STRLIT("HEAD"));
   831      self->last_content_before_send = NULL;
   832      h2o_doublebuffer_init(&self->sending, &h2o_socket_buffer_prototype);
   833      memset(&req->proxy_stats, 0, sizeof(req->proxy_stats));
   834      h2o_timer_init(&self->send_headers_timeout, on_send_headers_timeout);
   835      self->body_bytes_read = 0;
   836      self->body_bytes_sent = 0;
   837      self->pipe_reader.fds[0] = -1;
   838      self->pipe_inflight = 0;
   839      self->req_done = 0;
   840      self->res_done = 0;
   841
   842      return self;
   843  }
